def decimal_to_binary(decimal):
    """Convert a decimal number to binary format with 'db' prefix and suffix."""
    if decimal == 0:
        return "db0db"

    binary = []
    while decimal > 0:
        binary.append(str(decimal % 2))
        decimal = decimal // 2

    binary_str = ''.join(reversed(binary))
    return f"db{binary_str}db"

