from collections import deque

def minPath(grid, k):
    N = len(grid)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Create a mapping from value to its coordinates in the grid
    value_to_pos = {}
    for i in range(N):
        for j in range(N):
            value_to_pos[grid[i][j]] = (i, j)

    # Priority queue for Dijkstra's algorithm: (current_path, current_pos, visited_set)
    # We use a tuple where the first element is the path itself for lexicographical comparison
    heap = []
    # Initialize the heap with all possible starting positions
    for value in sorted(value_to_pos.keys()):
        i, j = value_to_pos[value]
        heapq.heappush(heap, ([value], (i, j), {value}))

    while heap:
        current_path, current_pos, visited = heapq.heappop(heap)
        if len(current_path) == k:
            return current_path

        if len(current_path) > k:
            continue

        i, j = current_pos
        for di, dj in directions:
            ni, nj = i + di, j + dj
            if 0 <= ni < N and 0 <= nj < N:
                value = grid[ni][nj]
                if value not in visited:
                    new_visited = set(visited)
                    new_visited.add(value)
                    new_path = current_path + [value]
                    heapq.heappush(heap, (new_path, (ni, nj), new_visited))

    return []
